mapper.insert:
INSERT INTO fire_119_sync_state(source_system,query_region_code,last_attempt_at,last_completed_at,last_full_scan_at,last_batch_id,last_result,last_reported_total,last_reported_pages,last_page_size,last_completed_page,consecutive_failures,last_error)
VALUES(#{source},#{region},#{started},#{completed},#{completed},#{batch},#{result},#{total},#{pages},#{pageSize},#{lastPage},#{failures},#{error})
ON DUPLICATE KEY UPDATE last_attempt_at=VALUES(last_attempt_at),last_completed_at=COALESCE(VALUES(last_completed_at),last_completed_at),last_full_scan_at=COALESCE(VALUES(last_full_scan_at),last_full_scan_at),last_batch_id=VALUES(last_batch_id),last_result=VALUES(last_result),last_reported_total=COALESCE(VALUES(last_reported_total),last_reported_total),last_reported_pages=COALESCE(VALUES(last_reported_pages),last_reported_pages),last_page_size=VALUES(last_page_size),last_completed_page=VALUES(last_completed_page),consecutive_failures=CASE WHEN VALUES(last_result)='success' THEN 0 WHEN VALUES(last_result)='running' THEN consecutive_failures ELSE consecutive_failures+1 END,last_error=VALUES(last_error),update_time=#{now}

mapper.select:
SELECT COUNT(*) AS total,COALESCE(SUM(a.street_match_status='inside'),0) AS insideCount,COALESCE(SUM(a.street_match_status='pending'),0) AS pendingCount,
COALESCE(SUM(a.street_match_status='outside'),0) AS outsideCount
FROM fire_119_incident a WHERE a.source_system=#{params.sourceSystem} ${params.dataScope}

SELECT a.* FROM () a WHERE 1=1 ${params.dataScope}
AND a.id=#{id}
AND (a.name LIKE CONCAT('%',#{keyword},'%') OR a.placeName LIKE CONCAT('%',#{keyword},'%') OR a.gatewayName LIKE CONCAT('%',#{keyword},'%'))
AND a.kind=#{kind}
AND a.gatewayId=#{gatewayId}
AND a.sourceCode=#{source}
AND a.sourceCode='119' AND a.caseTypeCode=#{caseType}
ORDER BY a.occurredAt DESC,a.id DESC
